import hashlib,json,os,pathlib,shutil,subprocess,sys,time
r=pathlib.Path(pathlib.Path('/tmp/tsr-member-cost-refresh-path').read_text().strip()); s=r/'source'; label=sys.argv[1]
def hashes():
 result={}
 for directory,dirs,files in os.walk(s):
  dirs[:]=[d for d in dirs if d not in ['target','.git']]
  for name in files:
   if name.endswith('.rs'):
    p=pathlib.Path(directory)/name; result[str(p.relative_to(s))]=hashlib.sha256(p.read_bytes()).hexdigest()
 return result
before=hashes(); cmd=['rtk','proxy','cargo','build','--offline','--release','-p','tsr','--bin','tsr']; env=os.environ.copy(); env['CARGO_BUILD_JOBS']='2'; env['CARGO_TARGET_DIR']=str(s/'target'); started=time.monotonic()
with (r/(label+'.stdout')).open('w') as out,(r/(label+'.stderr')).open('w') as err:
 p=subprocess.Popen(cmd,cwd=s,env=env,stdout=out,stderr=err); print(json.dumps({'label':label,'pid':p.pid,'command':cmd}),flush=True); rc=p.wait()
after=hashes(); assert before==after
record={'command':cmd,'pid':p.pid,'returncode':rc,'seconds':time.monotonic()-started,'source_unchanged_during_build':True,'source_hashes_before':before,'source_hashes_after':after,'stdout':(r/(label+'.stdout')).read_text(),'stderr':(r/(label+'.stderr')).read_text()}
if rc==0:
 exe=r/(label+'-tsr'); shutil.copy2(s/'target/release/tsr',exe); record['binary']={'path':str(exe),'sha256':hashlib.sha256(exe.read_bytes()).hexdigest()}
(r/(label+'.json')).write_text(json.dumps(record,indent=2)+'\n'); assert json.loads((r/(label+'.json')).read_text())==record; print(json.dumps({'label':label,'returncode':rc,'seconds':record['seconds']})); print(record['stderr'][-1500:]); sys.exit(rc)

