import hashlib,importlib.util,inspect,json,os,pathlib,shutil,sys,time
sys.dont_write_bytecode=True
r=pathlib.Path(pathlib.Path('/tmp/tsr-member-cost-refresh-path').read_text().strip());repo=pathlib.Path('<repo>');spec=importlib.util.spec_from_file_location('perf',repo/'scripts/whole_project_perf.py');perf=importlib.util.module_from_spec(spec);spec.loader.exec_module(perf)
original=inspect.getsource(perf.process);needle='        timed_out = threading.Event()';assert original.count(needle)==1;adapted=original.replace(needle,'        spawn_returned_unix_ns = time.time_ns()\n'+needle,1).replace('"pid": child.pid,','"pid": child.pid, "spawn_returned_unix_ns": spawn_returned_unix_ns,',1);namespace=dict(perf.__dict__);exec(adapted,namespace);process=namespace['process'];(r/'entry-process-adapter.py').write_text(adapted)
for key in list(os.environ):
 if key.startswith(('TSR_','TSGO_','RAYON_')):os.environ.pop(key)
os.environ['TSR_ENTRY_PROBE']='1';project=r/'source/benches/projects/domain-model-large/tsconfig.json';b=json.loads((r/'entry-build.json').read_text())['binary'];assert hashlib.sha256(pathlib.Path(b['path']).read_bytes()).hexdigest()==b['sha256'];expected=json.loads((r/'public-baseline.json').read_text())['rows'][0]['diagnostics']['fingerprint'];rows=[]
for label in ['entry-build','entry-fresh-path']:
 p=pathlib.Path(b['path']) if label=='entry-build' else r/label
 if label!='entry-build':shutil.copyfile(b['path'],p);p.chmod(pathlib.Path(b['path']).stat().st_mode)
 for index in range(2):
  cmd=[str(p),'--project',str(project),'--pretty','false','--noEmit','--incremental','false','--composite','false','--extendedDiagnostics'];v=process(cmd,project.parent,90);entries=[line.split(' ',1)[1] for line in v['stderr'].splitlines() if line.startswith('ENTRY_PROBE ')];assert len(entries)==1;entry_ns=int(entries[0]);v.update(label=label,index=index,binary_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),entry_unix_ns=entry_ns,spawn_seconds=(v['spawn_returned_unix_ns']-v['started_at_unix_ns'])/1e9,entry_after_spawn_start_seconds=(entry_ns-v['started_at_unix_ns'])/1e9,diagnostics=perf.diagnostics(v['stdout'],project.parent));rows.append(v);(r/'entry-progress.json').write_text(json.dumps({'rows':rows},indent=2)+'\n');assert json.loads((r/'entry-progress.json').read_text())['rows']==rows
  assert not v['timed_out'] and v['exit_code']==1 and v['diagnostics']['fingerprint']==expected
  print(json.dumps({k:v[k] for k in ['label','index','pid','wall_seconds','user_seconds','system_seconds','spawn_seconds','entry_after_spawn_start_seconds']}),flush=True)
record={'rows':rows,'complete':True,'baseline_source':'bb982558a98d8a3ee7e2ddfa4876ee22b5186251','private_main_probe_only':True,'canonical_runtime_changed':False,'driver_sha256':hashlib.sha256(pathlib.Path(__file__).read_bytes()).hexdigest(),'adapted_process_sha256':hashlib.sha256(adapted.encode()).hexdigest()};(r/'entry.json').write_text(json.dumps(record,indent=2)+'\n');assert json.loads((r/'entry.json').read_text())==record

