import datetime,hashlib,importlib.util,json,os,pathlib,shutil,sys
sys.dont_write_bytecode=True
r=pathlib.Path(pathlib.Path('/tmp/tsr-member-cost-refresh-path').read_text().strip());spec=importlib.util.spec_from_file_location('perf',pathlib.Path('<repo>/scripts/whole_project_perf.py'));perf=importlib.util.module_from_spec(spec);spec.loader.exec_module(perf)
for key in list(os.environ):
 if key.startswith(('TSR_','TSGO_','RAYON_')):os.environ.pop(key)
roles={'tsr':r/'baseline-pinned-build-tsr','native':pathlib.Path('<native-binary>')};rows=[]
for role,origin in roles.items():
 target=r/(role+'-fresh-version');shutil.copyfile(origin,target);target.chmod(origin.stat().st_mode);h=hashlib.sha256(origin.read_bytes()).hexdigest();assert hashlib.sha256(target.read_bytes()).hexdigest()==h
 for i in range(2):
  v=perf.process([str(target),'--version'],r,90);v.update(role=role,index=i,binary_sha256=h);rows.append(v);(r/'version-launch-progress.json').write_text(json.dumps({'rows':rows},indent=2)+'\n');assert json.loads((r/'version-launch-progress.json').read_text())['rows']==rows;assert v['exit_code']==0 and not v['timed_out'] and v['stderr']=='';print(json.dumps({k:v[k] for k in ['role','index','pid','wall_seconds','user_seconds','system_seconds']}),flush=True)
before=(r/'tsr-fresh-version').stat().st_ino;renamed=r/'tsr-renamed-warm-version';(r/'tsr-fresh-version').rename(renamed);assert renamed.stat().st_ino==before
for i in range(2):
  v=perf.process([str(renamed),'--version'],r,90);v.update(role='tsr-renamed-same-inode',index=i,binary_sha256=hashlib.sha256(renamed.read_bytes()).hexdigest(),same_inode=True);rows.append(v);(r/'version-launch-progress.json').write_text(json.dumps({'rows':rows},indent=2)+'\n');assert v['exit_code']==0 and not v['timed_out'];print(json.dumps({k:v[k] for k in ['role','index','pid','wall_seconds','user_seconds','system_seconds']}),flush=True)
record={'rows':rows,'complete':True,'compiler_work':'version only; no parse/check','security_settings_changed':False,'signatures_modified':False,'driver_sha256':hashlib.sha256(pathlib.Path(__file__).read_bytes()).hexdigest()};(r/'version-launch.json').write_text(json.dumps(record,indent=2)+'\n');assert json.loads((r/'version-launch.json').read_text())==record
